class Solution {
    private int n, m;
    private List<Integer>[] posMap = new List[26];
    private int[][] memo;

    private int dp(int r, int k, String ring, String key) {
        if (k == m) return 0;
        if (memo[r][k] != -1) return memo[r][k];
        int minSteps = Integer.MAX_VALUE;
        int targetChar = key.charAt(k) - 'a';
        for (int nxt : posMap[targetChar]) {
            int diff = Math.abs(r - nxt);
            int dist = Math.min(diff, n - diff);
            minSteps = Math.min(minSteps, dist + 1 + dp(nxt, k + 1, ring, key));
        }
        return memo[r][k] = minSteps;
    }

    public int findRotateSteps(String ring, String key) {
        n = ring.length();
        m = key.length();
        for (int i = 0; i < 26; i++) posMap[i] = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            posMap[ring.charAt(i) - 'a'].add(i);
        }
        memo = new int[n][m];
        for (int i = 0; i < n; i++) Arrays.fill(memo[i], -1);
        return dp(0, 0, ring, key);
    }
}

var findRotateSteps = function(ring, key) {
    const n = ring.length;
    const m = key.length;
    const posMap = new Map();
    for (let i = 0; i < n; i++) {
        if (!posMap.has(ring[i])) posMap.set(ring[i], []);
        posMap.get(ring[i]).push(i);
    }

    const memo = Array.from({ length: n }, () => new Array(m).fill(-1));

    function dp(r, k) {
        if (k === m) return 0;
        if (memo[r][k] !== -1) return memo[r][k];
        let minSteps = Infinity;
        const target = key[k];
        const positions = posMap.get(target) || [];
        for (const nxt of positions) {
            const diff = Math.abs(r - nxt);
            const dist = Math.min(diff, n - diff);
            minSteps = Math.min(minSteps, dist + 1 + dp(nxt, k + 1));
        }
        memo[r][k] = minSteps;
        return minSteps;
    }

    return dp(0, 0);
};
